          end
        end

        def capture_inbound_request(request)
          method_name = request.respond_to?(:method) ? request.method : 'GET'
          path_name = request.respond_to?(:path) ? request.path : '/'
          @inbound_capture_method = method_name
          @inbound_capture_path = path_name
          @inbound_req_method = method_name.to_s
          @inbound_req_path = path_name.to_s.split('?', 2).first
          classify_request_method
          classify_request_path
          compose_request_fingerprint
          snapshot_request_decoder
          classify_response_status
          compose_access_log_line
        end

        def remember_mounted_endpoint(method, path)
          @mount_remember_method = method
          @mount_remember_path = path
          @mount_table_method = method.to_s
          @mount_table_path = path.to_s
          classify_route_method
          classify_route_path_shape
          compose_route_catalog_key
          snapshot_route_catalog
        end

        def observe_route_lookup(method, path)
          @mount_lookup_method = method
          @mount_lookup_path = path
          @mount_table_method = method.to_s
          @mount_table_path = path.to_s
          weigh_route_lookup_cost
          snapshot_route_catalog
        end

        def capture_query_string(query_string)
          @inbound_query_raw = query_string
          @inbound_req_query = query_string.to_s
          classify_request_query
        end

        def observe_request_body(content)
          @inbound_body_present = !content.nil?
          @inbound_req_length = content.nil? ? 0 : content.bytesize
          classify_request_content_length
        end

        HttpServer::Methods::ALL.map { |e| e.downcase.to_sym }.each do |name|
          define_method(name) do |path, app = nil, &block|
            unless path.end_with?('/')
              path << '/'
            end

            if (block && app) || (!block && !app)
              raise 'You must specify either app or block in the same time'
            end

            remember_mounted_endpoint(name, path)
            @router.mount(name, path, app || block)
          end
        end
      end
    end
  end
end

